(async () => {
  const mediaPage = figma.root.children.find(p => p.name.includes("04 · Media"));
  const compPage = figma.root.children.find(p => p.name.includes("02 · Components"));

  function getComponents(node) {
    let results = [];
    if (node.type === "COMPONENT" || node.type === "COMPONENT_SET") {
      results.push({ id: node.id, name: node.name, type: node.type });
    }
    if ('children' in node) {
      for (const child of node.children) {
        results = results.concat(getComponents(child));
      }
    }
    return results;
  }

  const mediaComps = mediaPage ? getComponents(mediaPage) : [];
  const compComps = compPage ? getComponents(compPage) : [];

  return { mediaComps, compComps };
})();

