    } else if (variant === "dark") {
      btn.fills = [{ type: "SOLID", color: DARK_BG }];
      textColor = WHITE;
    } else if (variant === "outline") {
      btn.fills = [];
      btn.strokes = [{ type: "SOLID", color: GRAY_200 }];
      btn.strokeWeight = 1;
      textColor = GRAY_900;
