(async () => {
  // Load fonts
  await figma.loadFontAsync({ family: "DM Sans", style: "Regular" });
  await figma.loadFontAsync({ family: "DM Sans", style: "Medium" });
  await figma.loadFontAsync({ family: "DM Sans", style: "Semi Bold" });
  await figma.loadFontAsync({ family: "DM Sans", style: "Bold" });

  const workspacePage = figma.root.children.find(p => p.name.includes("03 · Workspace")) || figma.currentPage;
  await figma.setCurrentPageAsync(workspacePage);

  // Clear existing items in workspace page if re-running
  for (const child of workspacePage.children) {
    child.remove();
  }

  // Colors
  const AMBER = { r: 1, g: 0.6745, b: 0.0706 }; // #FFAC12
  const DARK_BG = { r: 0.102, g: 0.102, b: 0.122 }; // #1A1A1F
  const WHITE = { r: 1, g: 1, b: 1 };
  const GRAY_50 = { r: 0.976, g: 0.976, b: 0.98 };
  const GRAY_100 = { r: 0.945, g: 0.945, b: 0.953 };
  const GRAY_200 = { r: 0.88, g: 0.88, b: 0.895 };
  const GRAY_400 = { r: 0.6, g: 0.6, b: 0.63 };
  const GRAY_600 = { r: 0.38, g: 0.38, b: 0.42 };
  const GRAY_900 = { r: 0.1, g: 0.1, b: 0.12 };

  // Helper functions
  function createInstance(id) {
    const node = figma.getNodeById(id);
    if (node && node.type === "COMPONENT") {
      return node.createInstance();
    }
    const frame = figma.createFrame();
    frame.name = "Placeholder";
    return frame;
  }

  function makeText(text, fontSize, weight = "Regular", color = GRAY_900) {
    const t = figma.createText();
    t.fontName = { family: "DM Sans", style: weight };
    t.fontSize = fontSize;
    t.characters = text;
    t.fills = [{ type: "SOLID", color: color }];
    return t;
  }

  function makeButton(label, variant = "primary", iconRight = true) {
    const btn = figma.createFrame();
    btn.name = "Button";
    btn.layoutMode = "HORIZONTAL";
    btn.primaryAxisAlignItems = "CENTER";
    btn.counterAxisAlignItems = "CENTER";
    btn.paddingLeft = 24;
    btn.paddingRight = 24;
    btn.paddingTop = 14;
    btn.paddingBottom = 14;
    btn.itemSpacing = 10;
    btn.cornerRadius = 8;

    let textColor = GRAY_900;
    if (variant === "primary") {
      btn.fills = [{ type: "SOLID", color: AMBER }];
      textColor = GRAY_900;
    } else if (variant === "dark") {
      btn.fills = [{ type: "SOLID", color: DARK_BG }];
      textColor = WHITE;
    } else if (variant === "outline") {
      btn.fills = [];
      btn.strokes = [{ type: "SOLID", color: GRAY_200 }];
      btn.strokeWeight = 1;
      textColor = GRAY_900;
    } else if (variant === "ghost") {
      btn.fills = [];
      textColor = GRAY_900;
      btn.paddingLeft = 0;
      btn.paddingRight = 0;
    }

    const txt = makeText(label, 15, "Semi Bold", textColor);
    btn.appendChild(txt);

    if (iconRight) {
      const icon = createInstance("3:3"); // Icon_Arrow_Right
      icon.resize(20, 20);
      btn.appendChild(icon);
    }
    return btn;
  }

