(async () => {
  const frame = figma.createFrame();
  const reactions = frame.reactions;
  let protoKeys = [];
  for (let k in frame) {
    if (k.toLowerCase().includes("proto") || k.toLowerCase().includes("flow") || k.toLowerCase().includes("react")) {
      protoKeys.push(k);
    }
  }
  frame.remove();
  return { reactions, protoKeys };
})();

